CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  configuration_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle_configuration IS NOT NULL
       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN
      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN
        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'
          USING ERRCODE = '42501',
                HINT = format(
                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',
                  TG_ARGV[0]
                );
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  configuration_changed =
    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration
    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;

  IF NOT configuration_changed THEN
    RETURN NEW;
  END IF;

  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN
    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'
      USING ERRCODE = '0A000';
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     AND NEW.lifecycle_configuration_generation IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     OR NEW.lifecycle_configuration_generation IS NULL
     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration
     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN
    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_animal_catalog_membership_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    -- Unchanged from 20260906162436: derive only when the caller said nothing.
    new.adoption_eligible := coalesce(new.adoption_eligible, new.type in ('cat', 'dog'));
    new.sponsorship_eligible := coalesce(new.sponsorship_eligible, new.type = 'sponsor');
  end if;
  -- On UPDATE the flags are left exactly as supplied. Correcting a species
  -- never changes which catalogues an animal belongs to.
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_animal_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_entity text := tg_table_name;
  v_entity_id text;
  v_detail jsonb;
  -- audit_log has its own, wider reader set than these tables: it admits every
  -- treasurer, while these hold staff-only notes or applicant/adopter personal
  -- data. Copying their values here would relay that content across the role
  -- boundary the source table draws, so only column names cross into audit_log.
  v_redacted boolean := tg_table_name in (
    'animal_profile_internal', 'adoption_applications', 'adopter_profile'
  );
begin
  if auth.uid() is null then
    return null; -- ignored for AFTER triggers; see the scope note in 20260803120000.
  end if;

  -- animal_profile_internal has no `id` column — its primary key is
  -- animal_id (references public.animals(id)). Every other audited table
  -- keys off `id`. Pick the right column per table rather than assuming `id`
  -- everywhere.
  if tg_table_name = 'animal_profile_internal' then
    v_entity_id := coalesce(new.animal_id, old.animal_id)::text;
  else
    v_entity_id := coalesce(new.id, old.id)::text;
  end if;

  if tg_op = 'DELETE' then
    v_detail := case
      when v_redacted then jsonb_build_object(
        'columns',
        (
          select coalesce(jsonb_agg(key order by key), '[]'::jsonb)
          from jsonb_each(to_jsonb(old)) as row_columns(key, value)
          where value <> 'null'::jsonb
        )
      )
      else jsonb_build_object('old', to_jsonb(old))
    end;
  elsif tg_op = 'UPDATE' then
    -- Store only the columns that actually changed; whole-row snapshots on every
    -- edit would bloat audit_log for no diagnostic gain.
    v_detail := jsonb_build_object(
      'changed',
      (
        select coalesce(
          case
            when v_redacted then jsonb_agg(key order by key)
            else jsonb_object_agg(key, jsonb_build_object('from', old_row.value, 'to', new_row.value))
          end,
          case when v_redacted then '[]'::jsonb else '{}'::jsonb end
        )
        from jsonb_each(to_jsonb(old)) as old_row(key, value)
        join jsonb_each(to_jsonb(new)) as new_row(key, value) using (key)
        where old_row.value is distinct from new_row.value
      )
    );
  else
    v_detail := case
      when v_redacted then jsonb_build_object(
        'columns',
        (
          select coalesce(jsonb_agg(key order by key), '[]'::jsonb)
          from jsonb_each(to_jsonb(new)) as row_columns(key, value)
          where value <> 'null'::jsonb
        )
      )
      else jsonb_build_object('new', to_jsonb(new))
    end;
  end if;

  insert into public.audit_log (actor_user_id, action, entity, entity_id, detail)
  values (
    auth.uid(),
    v_entity || '.' || lower(tg_op),
    v_entity,
    v_entity_id,
    v_detail
  );

  return null; -- ignored for AFTER row-level triggers regardless of value.
end;
$function$

CREATE OR REPLACE FUNCTION private.require_active_admin_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  removed_active_admin boolean;
begin
  if tg_op = 'DELETE' then
    removed_active_admin := old.role = 'admin' and old.status = 'active';
  else
    removed_active_admin := old.role = 'admin' and old.status = 'active'
      and (new.role <> 'admin' or new.status <> 'active');
  end if;

  if removed_active_admin and not exists (
    select 1 from public.admin_user
    where role = 'admin' and status = 'active'
  ) then
    raise exception 'last_active_admin' using errcode = 'P0001';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_animal_archived_with_audit(p_actor_user_id uuid, p_animal_id uuid, p_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_previous timestamptz;
  v_next timestamptz;
  v_now timestamptz;
begin
  if p_actor_user_id is null or p_animal_id is null or p_archived is null then
    raise exception 'invalid archive arguments' using errcode = '22023';
  end if;

  select a.retired_at into v_previous
  from public.animals a
  where a.id = p_animal_id
  for update;
  if not found then
    return jsonb_build_object('kind', 'not_found');
  end if;

  -- A retry must preserve the original retirement date and avoid a second audit.
  if (v_previous is not null) = p_archived then
    return jsonb_build_object(
      'kind', 'unchanged', 'id', p_animal_id, 'retired_at', v_previous
    );
  end if;

  v_now := clock_timestamp();
  v_next := case when p_archived then v_now else null end;
  update public.animals
  set retired_at = v_next, updated_at = v_now
  where id = p_animal_id;

  insert into public.audit_log (
    actor_user_id, action, entity, entity_id, "timestamp", detail
  )
  values (
    p_actor_user_id, 'animals.update', 'animals', p_animal_id::text, v_now,
    jsonb_build_object(
      'changed',
      jsonb_build_object(
        'retired_at', jsonb_build_object('from', v_previous, 'to', v_next)
      )
    )
  );

  return jsonb_build_object(
    'kind', case when p_archived then 'archived' else 'restored' end,
    'id', p_animal_id,
    'retired_at', v_next
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_animal_draft_image_upload(p_animal_id uuid, p_storage_path text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_path text;
begin
  if p_animal_id is null or p_storage_path is null then
    raise exception 'invalid_animal_draft_upload_intent' using errcode = '22023';
  end if;

  insert into public.animal_draft_image_upload_intent (
    storage_path, animal_id, expires_at
  ) values (
    p_storage_path, p_animal_id, pg_catalog.clock_timestamp() + interval '1 day'
  )
  on conflict (storage_path) do update
  set expires_at = greatest(
    public.animal_draft_image_upload_intent.expires_at,
    excluded.expires_at
  )
  where public.animal_draft_image_upload_intent.animal_id = excluded.animal_id
    and public.animal_draft_image_upload_intent.cleanup_claimed_at is null
  returning storage_path into v_path;

  if v_path is null then
    raise exception 'animal_draft_upload_cleanup_in_progress' using errcode = '55000';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_animal_draft_image_attached()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_path text;
  v_claimed_at timestamptz;
begin
  for v_path in
    select distinct paths.path
    from (
      select nullif(new.body->>'draft_image_path', '') as path
      union all
      select nullif(photo->>'draft_path', '') as path
      from pg_catalog.jsonb_array_elements(
        case when pg_catalog.jsonb_typeof(new.body->'gallery') = 'array'
          then new.body->'gallery'
          else '[]'::jsonb
        end
      ) as photo
    ) as paths
    where paths.path is not null
      and paths.path like new.id::text || '/%'
  loop
    select intent.cleanup_claimed_at into v_claimed_at
    from public.animal_draft_image_upload_intent as intent
    where intent.storage_path = v_path
      and intent.animal_id = new.id
    for update;

    if found then
      if v_claimed_at is not null then
        raise exception 'animal draft image is being cleaned up' using errcode = '55000';
      end if;
      update public.animal_draft_image_upload_intent
      set attached_at = pg_catalog.clock_timestamp()
      where storage_path = v_path;
    end if;
  end loop;
  return new;
end;
$function$
